// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;
    uint public minSumBefore;
    uint public minSumAfter;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _test(uint256 newVal) internal {
        vm.assume(newVal > 0);
        try c.Initialized() {} catch { return; }
        try c.MinSum() returns (uint256 __r) { minSumBefore = __r; } catch { return; }
        try c.SetMinSum(newVal) {
            minSumAfter = c.MinSum();
        } catch {
            minSumAfter = c.MinSum();
        }
        assertTrue(minSumAfter <= minSumBefore || minSumAfter == 0);
    }

    function testFuzz_test(uint256 newVal) public {
        _test(newVal);
    }

    receive() external payable {}
}
